exp2:
/// 2^x by Schraudolph's trick: x * 2^23 written into the bits, so the significand
/// holds the fraction and 2^f ~ 1 + f. Offset tuned for minimax relative error.
/// float only; x in the normal range.
template<typename T>
inline auto bits_exp2_tuned(T x) -> T
{
    const auto t = std::trunc((x + T(-0.04367744890360167)) * T(0x1p23));
    return std::bit_cast<float>(static_cast<std::uint32_t>(static_cast<std::int32_t>(t) + (127 << 23)));
}

log2:
/// log2(x) by Mitchell's trick: the bits read as a number, / 2^23 - 127, so log2(m) ~ m - 1. Offset tuned for minimax.
/// float only; x positive and normal.
template<typename T>
inline auto bits_log2_tuned(T x) -> T
{
    return static_cast<T>(std::bit_cast<std::uint32_t>(static_cast<float>(x))) * T(0x1p-23) - T(126.95696433397204);
}
